"use strict";
const key = { id: 1 };
const registry = new WeakMap([[key, "label"]]);
const seen = new WeakSet([key]);
exports.key = key;
exports.registry = registry;
exports.seen = seen;
exports.kind = (v) => Object.prototype.toString.call(v);
exports.label = (map, k) => map.get(k);
exports.has = (set, k) => set.has(k);
exports.isRegistry = (v) => v === registry;
exports.isSeen = (v) => v === seen;
